<?php
if(!teachingCalendarReady()){echo '<p>Run the database migration first.</p>';return;}
$calendars=all('SELECT * FROM teaching_calendars WHERE active=1 ORDER BY valid_from DESC');$timings=all('SELECT * FROM teaching_time_slots WHERE active=1 ORDER BY start_time');
if(!$calendars||!$timings){echo '<div class="notice">Admin must configure the academic calendar and class timings before manual entry.</div>';if($user['role']==='admin')echo '<a class="button" href="?page=att_calendar">Configure calendar and timings</a>';return;}
$t=$page==='att_edit'?one('SELECT t.*,u.email,c.room_code FROM tutor_timetable t JOIN users u ON u.id=t.staff_id LEFT JOIN classrooms c ON c.id=t.classroom_id WHERE t.id=?',[(int)($_GET['id']??0)]):[];
if($page==='att_edit'&&!$t){echo '<p>Class not found.</p>';return;}
$termId='';foreach($calendars as $c)if(($t['academic_year']??'')===$c['academic_year']&&($t['semester']??'')===$c['semester']&&($t['valid_from']??'')>=$c['valid_from']&&($t['valid_until']??'')<=$c['valid_until'])$termId=$c['id'];
$timingOptions=[];$timeId='';foreach($timings as $tm){$timingOptions[$tm['id']]=$tm['start_time'].' – '.$tm['end_time'];if(($t['start_time']??'')===$tm['start_time']&&($t['end_time']??'')===$tm['end_time'])$timeId=$tm['id'];}
$people=[];foreach(staff()as $s)if(teaching($s))$people[$s['email']]=$s['name'].' · '.$s['email'];$rooms=[];foreach(all('SELECT room_code FROM classrooms WHERE active=1 ORDER BY room_code')as $r)$rooms[$r['room_code']]=$r['room_code'];
?><section class="card"><h2><?=$t?'Edit class':'Enter class timetable manually'?></h2><p>Select the Admin-configured academic calendar and class timing. Dates and times are fixed by those settings. Teaching department means the department receiving the class; it may differ from the tutor’s home department.</p><?php attForm($t?'att_schedule_edit':'att_schedule_add');?><input type="hidden" name="id" value="<?=e($t['id']??0)?>"><div class="form-grid"><label class="full">Academic year / college calendar<select name="calendar_id" id="manual-calendar" required><option value="">Select calendar…</option><?php foreach($calendars as $c):?><option value="<?=$c['id']?>" data-semester="<?=e($c['semester'])?>" data-dates="<?=e($c['valid_from'].' to '.$c['valid_until'])?>" <?=$termId===$c['id']?'selected':''?>><?=e($c['academic_year'].' · Semester '.$c['semester'].' · '.$c['valid_from'].' to '.$c['valid_until'])?></option><?php endforeach;?></select></label>
<div class="full form-grid"><?php attSelect('row[Year]','Year',['I'=>'I','II'=>'II','III'=>'III','IV'=>'IV'],['','I','II','III','IV'][(int)($t['year_level']??0)]??'',true);attSelect('row[Semester]','Semester',['I'=>'I','II'=>'II'],$t['semester']??'',true);?></div>
<?php attSelect('row[Department]','Teaching department',array_combine(departments(),departments()),$t['department']??'',true);attSelect('row[Programme]','Programme',array_combine(programmes(),programmes()),$t['programme']??'',true);attInput('row[Section]','Section',$t['section']??'A');attSelect('row[Tutor Email]','Tutor', $people,$t['email']??'',true);attInput('row[Subject Code]','Module code',$t['subject_code']??'');attInput('row[Subject Name]','Module name',$t['subject_name']??'');attSelect('row[Day]','Day',array_combine(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']),['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][(int)($t['weekday']??0)],true);attSelect('time_slot_id','Class timing (start – end)', $timingOptions,$timeId,true);attSelect('row[Classroom]','Classroom',$rooms,$t['room_code']??'',false);attInput('row[Class Date]','Class date (optional; leave blank to repeat weekly)',$t['class_date']??'','date',false);?>
<div class="full"><?php attSelect('schedule_mode','Schedule',['weekly'=>'Weekly recurring','specific'=>'Specific date / research class'],!empty($t['class_date'])?'specific':'weekly',true);attInput('row[Student Count]','Total students (optional)',$t['student_count']??'','number',false);?></div>
<div class="full form-grid"><?php attSelect('row[Delivery Mode]','Delivery mode',['In person'=>'In person','Online'=>'Online'],$t['delivery_mode']??'In person',true);attSelect('row[Attendance Required]','Attendance required',['Yes'=>'Yes','No'=>'No'],($t['attendance_required']??1)?'Yes':'No',true);attSelect('row[Flexible]','Allow tutor to reschedule',['No'=>'No','Yes'=>'Yes'],!empty($t['flexible'])?'Yes':'No',true);?><p>Online classes require Attendance required: No and do not reserve a classroom. Flexible sessions must use a specific date for tutor editing.</p></div><div class="full"><h3>Additional participating groups</h3><p>For a combined class, add every other student group attending this same session. The tutor confirms attendance once. Use Class date above for an occasional research class.</p><div id="participant-groups"><?php $extra=$t?array_slice(sessionGroups($t),1):[];foreach($extra as $i=>$g){renderParticipantFields((string)$i,$g);}?></div><button type="button" id="add-participant" class="secondary">Add participating group</button></div>
<p class="full">Fixed valid dates: <output id="manual-calendar-dates">Select an academic calendar above.</output></p></div><button>Save class</button></form></section>

<?php function renderParticipantFields(string $i,array $g=[]):void{?><fieldset class="form-grid participant-group"><legend>Participating student group</legend><?php attSelect("groups[$i][department]",'Department',array_combine(departments(),departments()),$g['department']??'',true);attSelect("groups[$i][programme]",'Programme',array_combine(programmes(),programmes()),$g['programme']??'',true);attSelect("groups[$i][year_level]",'Year',[1=>'I',2=>'II',3=>'III',4=>'IV'],$g['year_level']??1,true);attInput("groups[$i][section]",'Section',$g['section']??'A');?><button type="button" class="remove-participant secondary">Remove group</button></fieldset><?php } ?>
<template id="participant-template"><?php renderParticipantFields('__INDEX__');?></template>
